#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b) {
    return a < b ? a : b;
}
int mx(int a, int b) {
    return a > b ? a : b;
}
int read(void) {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a) {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x) {
    printf("%d ", x);
}
void emitstr(int* a, int n) {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void) {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int head = 0, i = 0, k = 0, n = 0, tail = 0;
    n = read();
    // k 是固定窗口长度，a 保存数值，b 保存最大值候选的下标。
    k = read();
    for (i = 0; i < n; i += 1) {
        a[i] = read();
    }
    head = 0;
    tail = 0;
    for (i = 0; i < n; i += 1) {
        // 先删除已离开窗口左边界的候选下标。
        while ((head < tail) && (b[head] <= (i - k))) {
            head = (head + 1);
        }
        // 新元素更大或相等且更晚过期，旧队尾不会再成为必要候选。
        while ((head < tail) && (a[b[(tail - 1)]] <= a[i])) {
            tail = (tail - 1);
        }
        b[tail] = i;
        tail = (tail + 1);
        // 只有完整窗口形成后才输出队首对应的最大值。
        if (i >= (k - 1)) {
            emit(a[b[head]]);
        }
    }
    return 0;
}

