use std::io::{self, Read};
fn mn(a: i32, b: i32) -> i32 {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32 {
    a.max(b)
}
fn emit(x: i32) {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32) {
    if n == 0 {
        print!("-");
    }
    for i in 0..n {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader {
    t: Vec<String>,
    p: usize,
}
impl Reader {
    fn new() -> Self {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32 {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32 {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-" {
            return 0;
        }
        for (i, c) in s.bytes().enumerate() {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main() {
    let mut reader = Reader::new();
    let mut a = vec![0i32; 20000];
    let mut b = vec![0i32; 20000];
    let mut d = vec![0i32; 20000];
    let mut e = vec![0i32; 20000];
    let mut head: i32 = 0;
    let mut i: i32 = 0;
    let mut k: i32 = 0;
    let mut n: i32 = 0;
    let mut tail: i32 = 0;
    n = reader.read();
    // k 是固定窗口长度，a 保存数值，b 保存最大值候选的下标。
    k = reader.read();
    i = 0;
    while i < n {
        a[(i) as usize] = reader.read();
        i += 1;
    }
    head = 0;
    tail = 0;
    i = 0;
    while i < n {
        // 先删除已离开窗口左边界的候选下标。
        while ((head < tail) && (b[(head) as usize] <= (i - k))) {
            head = (head + 1);
        }
        // 新元素更大或相等且更晚过期，旧队尾不会再成为必要候选。
        while ((head < tail) && (a[(b[(tail - 1) as usize]) as usize] <= a[(i) as usize])) {
            tail = (tail - 1);
        }
        b[(tail) as usize] = i;
        tail = (tail + 1);
        // 只有完整窗口形成后才输出队首对应的最大值。
        if (i >= (k - 1)) {
            emit(a[(b[(head) as usize]) as usize]);
        }
        i += 1;
    }
}
